import { readFileSync } from "node:fs";
import { test } from "uvu";
import * as assert from "uvu/assert";
import scss from "postcss-scss";
import prettier from "prettier";
import plugin from "../src/index.mjs";
import { grundyPropSorter } from "../src/grundy-prop-sorter.mjs";
import { presets } from "../src/presets/index.mjs";

// Frozen outputs from the published baseline, not generated by the test.
const fixture = JSON.parse(readFileSync(new URL("fixtures/sorting-units.json", import.meta.url), "utf8"));

test("Comments and nested dependencies retain exact output across sorting options", async () => {
    const configurations = [];
    for (const preset of Object.keys(presets))
        for (const safety of ["strict", "loose"])
            for (const withRoot of [false, true])
                for (const splitGroups of [false, true])
                    configurations.push([preset, safety, withRoot, splitGroups].join("/"));
    assert.equal(Object.keys(fixture.expected), configurations);
    assert.is(fixture.sources.length, 5);
    let cases = 0;
    for (const key of configurations) {
        const [name, safety, root, split] = key.split("/"),
            preset = presets[name];
        const options = {
            presetGroups: preset.groups,
            order: preset.order,
            safety,
            withRoot: root === "true",
            splitGroups: split === "true"
        };
        assert.is(fixture.expected[key].length, fixture.sources.length);
        for (const [i, { id, input }] of fixture.sources.entries()) {
            const expected = fixture.outputs[fixture.expected[key][i]];
            assert.type(expected, "string");
            const tree = scss.parse(input);
            grundyPropSorter(options).OnceExit(tree);
            assert.is(tree.toString(scss.stringify), expected, `${id}/${key}`);
            const config = {
                parser: "scss",
                plugins: [plugin],
                grundyScssSorterPreset: name,
                grundyScssSorterSafety: safety,
                grundyScssSorterWithRoot: options.withRoot,
                grundyScssSorterSplitGroup: options.splitGroups
            };
            const formatted = await prettier.format(input, config);
            assert.is(formatted, await prettier.format(expected, { parser: "scss" }), `${id}/${key} public output`);
            assert.is(await prettier.format(formatted, config), formatted, `${id}/${key} public idempotence`);
            cases++;
        }
    }
    assert.is(cases, 200);
});

test.run();
